# 1. 统计字符串中每个单词的出现次数
text = 'hello world hello python world hello'
words = text.split()
word_counts = {}
for word in words:
    word_counts[word] = word_counts.get(word, 0) + 1
print(word_counts)  # {'hello': 3, 'world': 2, 'python': 1}

# 2. 驼峰命名转下划线命名
def camel_to_snake(s):
    result = ''
    for i, c in enumerate(s):
        if c.isupper() and i > 0:
            result += '_'
        result += c.lower()
    return result

print(camel_to_snake('getElementById'))  # get_element_by_id

# 3. 检查回文字符串
def is_palindrome(s):
    s = s.lower().replace(' ', '')
    return s == s[::-1]

print(is_palindrome('A man a plan a canal Panama'))  # True

# 4. 简单的文本压缩（RLE）
def rle_encode(s):
    if not s:
        return ''
    result = []
    count = 1
    for i in range(1, len(s)):
        if s[i] == s[i-1]:
            count += 1
        else:
            result.append(f'{s[i-1]}{count}' if count > 1 else s[i-1])
            count = 1
    result.append(f'{s[-1]}{count}' if count > 1 else s[-1])
    return ''.join(result)

print(rle_encode('aaabbbccda'))  # a3b3c2d1a1
